<?php require '_init.php';$title='Produits';$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$act=$_POST['act']??'';if($act==='del'){$pdo->prepare("DELETE FROM products WHERE id=?")->execute([(int)$_POST['id']]);flash('Produit supprimé.');go('products.php');}$n=trim($_POST['name']??'');$cat=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=max(0,(int)($_POST['stock']??0));$brand=trim($_POST['brand']??'');$desc=trim($_POST['description']??'');$image=trim($_POST['image']??'');if(!$n||!$cat||$price<0)flash('Champs invalides.','danger');else{$slug='item-'.bin2hex(random_bytes(6));$s=$pdo->prepare("INSERT INTO products(category_id,name,slug,brand,description,price,stock,status) VALUES(?,?,?,?,?,?,?,'active')");$s->execute([$cat,$n,$slug,$brand,$desc,$price,$stock]);$id=$pdo->lastInsertId();if($image)$pdo->prepare("INSERT INTO product_images(product_id,image_path,is_main) VALUES(?,?,1)")->execute([$id,$image]);flash('Produit ajouté.');go('products.php');}}$ps=$pdo->query("SELECT p.*,c.name cat FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();require '../includes/header.php';?><section class="banner"><div class="container"><h1>GESTION PRODUITS</h1></div></section><section class="container section"><div class="adminnav"><a href="dashboard.php">Dashboard</a><a href="products.php">Produits</a><a href="categories.php">Catégories</a><a href="orders.php">Commandes</a><a href="users.php">Utilisateurs</a></div><form class="form" method="post"><h2>Ajouter un produit</h2><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Nom<input required name="name"></label><label>Catégorie<select name="category_id"><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></label><label>Marque<input name="brand"></label><label>Prix TND<input type="number" min="0" step=".001" name="price" required></label><label>Stock<input type="number" min="0" name="stock" value="0"></label><label>Chemin image<input name="image" placeholder="assets/images/produit.jpg"></label><label>Description<textarea name="description"></textarea></label><button class="btn">Ajouter</button></form><h2>Produits existants</h2><div class="tablewrap"><table><tr><th>Nom</th><th>Catégorie</th><th>Prix</th><th>Stock</th><th>Action</th></tr><?php foreach($ps as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['cat'])?></td><td><?=money($p['price'])?></td><td><?=(int)$p['stock']?></td><td><form method="post" onsubmit="return confirm('Supprimer ?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="act" value="del"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="dangerbtn">Supprimer</button></form></td></tr><?php endforeach?></table></div></section><?php require '../includes/footer.php';?>
